let currentModule='workbench',currentView='dashboard',adminRole=sessionStorage.getItem('venture-admin-role')||'administrator',tableSequence=0,sessionPermissions=['*'];
const viewPermissions={dashboard:'dashboard.read',todo:'dashboard.read',risks:'dashboard.read',members:'membership.summary.read','membership-decisions':'membership.summary.read','crm-verifications':'crm.read','directory-profiles':'directory.read','public-profile-updates':'directory.read','employment-verifications':'artifact.metadata.read','renewal-offers':'membership.summary.read',orders:'payment.read','migration-center':'content.read','membership-rehearsal':'membership.summary.read','local-materials':'content.read','crm-import':'crm.read','feishu-onetime':'content.read',resources:'content.read','knowledge-import':'content.read','voluntary-directory-import':'directory.read','shop-order-import':'payment.read','payment-evidence':'payment.read','import-batches':'content.read','import-items':'content.read',activities:'activity.read',registrations:'activity.read','notification-jobs':'activity.read','activity-archives':'activity.read','matching-rehearsal':'matching.read',demands:'matching.read','ai-reviews':'matching.read',applications:'matching.read','member-connections':'matching.read','audit-logs':'audit.read',governance:'dashboard.read','release-checks':'release.read'};
function canView(view){return sessionPermissions.includes('*')||sessionPermissions.includes(viewPermissions[view]||'dashboard.read')}
function firstAllowedView(module){return module.views.find(([key])=>canView(key))?.[0]}
function refreshNavigationPermissions(){modules.forEach(module=>{const button=nav.querySelector(`[data-module="${module.key}"]`),allowed=Boolean(firstAllowedView(module));button.disabled=!allowed;button.title=allowed?'':'当前角色无可用视图'})}

function esc(value){return String(value??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function display(value){if(Array.isArray(value))return value.map(x=>statusNames[x]||x).join('、');if(typeof value==='boolean')return value?'是':'否';return statusNames[value]||value}
function tableCell(key,value){const safe=esc(display(value));if(['title','anonymousTitle'].includes(key))return `<span class="clamp-title" title="${safe}">${safe}</span>`;return ['status','reviewStatus','verificationStatus','finalStatus'].includes(key)?`<span class="pill">${safe}</span>`:safe}
function table(rows){if(!rows.length)return '<div class="hint">当前筛选下暂无记录。</div>';const keys=Object.keys(rows[0]).filter(k=>labels[k]).slice(0,8),id=`data-table-${++tableSequence}`,statuses=[...new Set(rows.map(x=>x.status||x.reviewStatus||x.verificationStatus||x.finalStatus).filter(Boolean))];return `<div class="panel"><div class="table-tools"><input aria-label="搜索当前列表" placeholder="搜索当前列表" oninput="filterTable('${id}')"><select aria-label="按状态筛选" onchange="filterTable('${id}')"><option value="">全部状态</option>${statuses.map(x=>`<option value="${esc(x)}">${esc(display(x))}</option>`).join('')}</select><span class="muted">共 ${rows.length} 条</span></div><table id="${id}"><thead><tr>${keys.map(k=>`<th>${labels[k]}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr data-status="${esc(row.status||row.reviewStatus||row.verificationStatus||row.finalStatus||'')}" data-search="${esc(JSON.stringify(row).toLowerCase())}">${keys.map(k=>`<td>${tableCell(k,row[k])}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="table-empty">没有符合条件的记录。</div></div>`}
function filterTable(id){const table=document.querySelector(`#${id}`),panel=table.closest('.panel'),query=panel.querySelector('input').value.trim().toLowerCase(),status=panel.querySelector('select').value;let visible=0;table.querySelectorAll('tbody tr').forEach(row=>{const show=(!query||row.dataset.search.includes(query))&&(!status||row.dataset.status===status);row.hidden=!show;if(show)visible++});panel.querySelector('.table-empty').style.display=visible?'none':'block'}
async function requestJson(url,options={}){const headers={...(options.headers||{}),'x-demo-role':adminRole};const response=await fetch(url,{...options,headers});const data=await response.json();if(!response.ok){const error=new Error(data.error||'操作失败');error.code=data.code;throw error}return data}
function idempotencyKey(){return `demo-${Date.now()}-${Math.random().toString(16).slice(2)}`}
async function confirmedJson(url,options,action,message){if(!confirm(message))throw new Error('已取消操作');return requestJson(url,{...options,headers:{...(options?.headers||{}),'x-admin-confirmation':action,'idempotency-key':idempotencyKey()}})}
function moduleForView(view){return modules.find(m=>m.views.some(v=>v[0]===view))}

modules.forEach(module=>{const button=document.createElement('button');button.dataset.module=module.key;button.textContent=module.label;button.onclick=()=>{const target=firstAllowedView(module);if(target)navigate(module.key,target)};nav.appendChild(button)});
async function navigate(moduleKey,viewKey){currentModule=moduleKey;const module=modules.find(x=>x.key===moduleKey),allowedViews=module.views.filter(([key])=>canView(key));if(!allowedViews.length){content.innerHTML='<div class="hint">当前角色在此模块没有可用视图。</div>';return}const view=allowedViews.find(x=>x[0]===viewKey)||allowedViews[0];currentView=view[0];document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.module===moduleKey));subnav.innerHTML='';allowedViews.forEach(([key,label])=>{const button=document.createElement('button');button.textContent=label;button.classList.toggle('active',key===view[0]);button.onclick=()=>navigate(moduleKey,key);subnav.appendChild(button)});breadcrumb.textContent=module.label;title.textContent=view[1];subtitle.textContent=module.description;content.innerHTML='<div class="loading">正在载入…</div>';await refreshGlobalTodo();await loadView(view[0])}
function load(view){const module=moduleForView(view);return navigate(module?.key||currentModule,view)}

async function refreshGlobalTodo(){try{const data=await requestJson('/api/admin/dashboard');const m=data.metrics;globalTodo.innerHTML=`<div class="todo-strip"><b>全局待办</b><button class="todo-chip warn" onclick="load('members')">会籍待复核 ${m.pendingMembershipReviews}</button><button class="todo-chip" onclick="load('public-profile-updates')">公开名册待审核 ${m.pendingProfileReviews}</button><button class="todo-chip" onclick="load('employment-verifications')">在职核验 ${m.pendingEmploymentReviews}</button><button class="todo-chip" onclick="load('import-items')">导入异常 ${m.importErrorItems||0}</button><button class="todo-chip" onclick="load('notification-jobs')">通知重试 ${m.notificationRetries||0}</button></div>`}catch{globalTodo.innerHTML=''}}

const selectedWorkbenchFiles={};
async function spreadsheetPayload(file){if(!file)throw new Error('请先选择 .xlsx 或 .csv 文件');const extension=(file.name.split('.').pop()||'').toLowerCase();if(!['xlsx','csv'].includes(extension))throw new Error('仅支持 .xlsx 和 .csv；旧版 .xls 与宏文件不支持');if(file.size>10*1024*1024)throw new Error('文件超过 10MB 安全硬上限，请按导出月份或时间段分批');if(extension==='csv')return {format:'csv',csv:await file.text()};const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=32768)binary+=String.fromCharCode(...bytes.subarray(offset,offset+32768));return {format:'xlsx',dataBase64:btoa(binary)}}
function setWorkbenchFile(kind,files){const file=files?.[0],state=document.querySelector('#workbench-file-state'),button=document.querySelector('#workbench-preview');delete selectedWorkbenchFiles[kind];button.disabled=true;if(!file){state.textContent='尚未选择文件。';return}const extension=(file.name.split('.').pop()||'').toLowerCase();if(!['xlsx','csv'].includes(extension)){state.textContent='未读取：仅支持 .xlsx 和 .csv；旧版 .xls 与宏文件不支持。';return}if(file.size>10*1024*1024){state.textContent='未读取：超过 10MB 安全硬上限，请按导出月份或时间段分批。';return}selectedWorkbenchFiles[kind]=file;state.textContent=`已选择 ${extension.toUpperCase()}（不回显文件名）；可运行安全预检。`;button.disabled=false}
async function renderImportWorkbench(kind){const configs={knowledge:{template:'knowledge.csv',title:'旧资料 CSV 清单预检',note:'仅用于已有清单；电脑文件请回到“从电脑导入资料”。',fields:'标题、摘要、来源目录、资料类型、标签、访问级别、来源审核状态'},crm_verification:{template:'internal-crm',title:'内部 CRM 核验导入',note:'只进入 CRM 私有复核域；群状态未知、未核验或冲突均不能激活会籍。',fields:'内部会员引用、匹配令牌、CRM 核验状态、会籍起止、群状态、证据备注、迁移状态'},voluntary_directory:{template:'voluntary-directory',title:'自愿公开名册导入',note:'必须明确同意并独立人工审核；绝不从 CRM 或付款证据自动生成。',fields:'会员引用、公开名、机构/行业/兴趣、同意状态、申请对接规则、来源表、迁移状态'},shop_order_evidence:{template:'wechat-shop-orders',title:'付款证据导入',note:'只形成付款证据候选；退款与商品规则必须复核，单笔订单绝不自动激活会籍。',fields:'下单时间、标准订单状态、受保护匹配字段、收退款、产品规则、来源批次'}};const config=configs[kind];if(kind==='knowledge'){const sample=await fetch(`/api/admin/import-templates/${config.template}`).then(r=>r.text());content.innerHTML=`<div class="panel"><h2>${config.title}</h2><p class="muted">${config.note}</p><textarea id="csv-input" class="csv-input">${esc(sample.replace(/^\uFEFF/,''))}</textarea><button class="primary" onclick="previewImport('${kind}')">运行预检</button></div><div id="import-result"></div>`;return}content.innerHTML=`<div class="panel"><h2>${config.title}</h2><p class="muted">${config.note}</p><div class="mapping-note"><b>模板字段</b><span>${esc(config.fields)}</span></div><p><a class="download" href="/api/admin/import-templates/${config.template}.xlsx">下载 Excel 模板</a> · <a class="download" href="/api/admin/import-templates/${config.template}.csv">下载 CSV 模板</a></p><div class="local-drop" ondragover="event.preventDefault()" ondrop="event.preventDefault();setWorkbenchFile('${kind}',event.dataTransfer.files)" onclick="document.querySelector('#workbench-file').click()"><b>选择 .xlsx 或 .csv，或拖放到这里</b><span id="workbench-file-state">常规整表无需拆分；安全硬上限 10MB、10,000 行，读取第一个有内容的可见工作表。</span><input id="workbench-file" type="file" hidden accept=".xlsx,.csv" onchange="setWorkbenchFile('${kind}',this.files)"></div><div class="hint">预检会显示已读取行数、异常行数和标准字段映射；不回显手机号、微信、金额、订单号或备注正文，也不写入正式事实域。</div><button id="workbench-preview" class="primary" disabled onclick="previewImport('${kind}')">运行预检</button></div><div id="import-result"></div>`}
async function openMemberSpreadsheetImport(kind){title.textContent=kind==='crm_verification'?'导入 CRM Excel':'导入自愿名册 Excel';await renderImportWorkbench(kind)}
let feishuReadiness=null,feishuPageBlocker=null;
function renderFeishuSteps(readiness){return `<div class="feishu-steps">${readiness.steps.map((step,index)=>`<div class="feishu-step ${esc(step.status)}"><span class="step-index">${index+1}</span><div><b>${esc(step.label)}</b><span class="step-status">${esc(display(step.status))}</span><p>${esc(step.detail)}</p></div></div>`).join('')}</div>`}
function feishuNextButtonLabel(action){if(feishuPageBlocker?.type==='wiki_permission')return '查看授权修复并重试';return ({CONFIGURE_SERVER_SECRETS:'查看本机配置步骤',TEST_CONNECTION:'立即测试连接',FIX_CONNECTION:'查看连接修复步骤',CONFIGURE_PRIVATE_STORAGE:'查看私有存储步骤',GRANT_WIKI_AND_CREATE_TASK:'填写根 Wiki 链接'})[action]||'查看下一步'}
function handleFeishuNextAction(){if(feishuPageBlocker?.type==='wiki_permission'){document.querySelector(`#feishu-task-${CSS.escape(feishuPageBlocker.taskId)}`)?.scrollIntoView({behavior:'smooth',block:'center'});return}const action=feishuReadiness?.nextAction;if(action==='TEST_CONNECTION')return testFeishuConnection();if(action==='GRANT_WIKI_AND_CREATE_TASK'){document.querySelector('#fm-root')?.focus();document.querySelector('#fm-root')?.scrollIntoView({behavior:'smooth',block:'center'});return}const messages={CONFIGURE_SERVER_SECRETS:'在项目目录双击 configure-feishu-local.command，保存 .env.local 后双击 restart-preview.command。后台不会接收 Secret。',FIX_CONNECTION:'根据安全错误分类检查本机私密配置，保存后重启服务，再点测试连接。',CONFIGURE_PRIVATE_STORAGE:'本机联调保留 PRIVATE_STORAGE_DIR=./server/private-storage；正式迁入仍需先选择并接入私有对象存储。'};alert(messages[action]||feishuReadiness?.nextActionText||'请按迁入前检查继续')}
function updateFeishuFormState(){const source=document.querySelector('#fm-source'),root=document.querySelector('#fm-root'),button=document.querySelector('#fm-preflight');if(!source||!button)return;const official=source.value==='official_readonly';root.disabled=!official;button.disabled=official&&!feishuReadiness?.canCreateOfficialTask;button.title=button.disabled?'请先完成服务端配置并测试连接':'';document.querySelector('#fm-form-note').textContent=official?(button.disabled?'完成服务端配置与连接测试后，才能创建官方只读任务。':'确认已在飞书侧授予目标 Wiki 读权，再粘贴根链接。'):'离线资料包必须通过生产私有上传通道提交；当前页面不接收文件。';const head=document.querySelector('.migration-guide .panel-head');if(head&&!document.querySelector('#feishu-next-action')){const next=document.createElement('button');next.id='feishu-next-action';next.className='primary';next.onclick=handleFeishuNextAction;head.appendChild(next)}const next=document.querySelector('#feishu-next-action');if(next)next.textContent=feishuNextButtonLabel(feishuReadiness?.nextAction)}
async function renderFeishuMigration(){const [readiness,tasks]=await Promise.all([requestJson('/api/admin/feishu-migration-readiness'),requestJson('/api/admin/feishu-migrations')]);feishuReadiness=readiness;const details=await Promise.all(tasks.map(x=>requestJson(`/api/admin/feishu-migrations/${x.id}`)));const connection=readiness.connection;content.innerHTML=`<div class="panel migration-guide"><div class="panel-head"><div><h2>一次性飞书迁入 · 迁入前检查</h2><p class="muted">当前环境：${readiness.environmentMode==='production'?'生产部署':'本地演示 / 开发'}</p></div><span class="pill">下一步：${esc(readiness.nextActionText)}</span></div><div class="warning">创建了飞书应用，不等于当前服务已读取到凭据；连接成功也不等于目标 Wiki 已授权。配置变更后需要重启服务。</div>${renderFeishuSteps(readiness)}<div class="security-line">后台绝不接收 App Secret、token、存储路径或原始飞书响应。</div></div><div class="panel connection-panel"><div class="panel-head"><h2>应用身份连接 · <span class="pill">${esc(display(connection.status))}</span></h2><button class="secondary" ${connection.configured?'':'disabled'} onclick="testFeishuConnection()">测试连接</button></div><div class="${connection.status==='connection_failed'||connection.status==='not_configured'?'warning':'hint'}">${connection.configured?'测试只验证 App ID / Secret 能否取得应用身份，不验证目标 Wiki 资源读权。':'请在部署平台或本机私密启动环境配置 FEISHU_APP_ID、FEISHU_APP_SECRET，重启服务后再回来。'}</div>${connection.lastTestAt?`<p class="muted">最近测试：${esc(connection.lastTestAt)}</p>`:''}${connection.errorCategory?`<p class="muted">安全错误分类：${esc(display(connection.errorCategory))}</p>`:''}</div><div class="panel"><h2>创建预检任务</h2><div class="hint">预检只校验并安全保存任务所需的私有节点引用；首次“运行迁入”才会验证目标 Wiki 是否真正授予应用读权并读取目录。</div><label>飞书 Wiki 根链接（提交后不回显、不写日志）<input id="fm-root" class="form-input" autocomplete="off" placeholder="粘贴已授权 Wiki 的 HTTPS 根链接"></label><div class="form-grid"><label>迁入来源<select id="fm-source" class="form-input" onchange="updateFeishuFormState()"><option value="official_readonly">飞书自建应用只读授权</option><option value="export_package">离线导出资料包</option></select></label><label>抓取范围<select id="fm-scope" class="form-input"><option value="all_descendants">根目录全部子项</option><option value="selected_directories">仅选择的目录</option></select></label><label>分类策略<select id="fm-strategy" class="form-input"><option value="directory_first">目录优先 + 内容辅助</option><option value="content_inference">内容识别优先</option><option value="manual_first">全部人工分类</option></select></label></div><button id="fm-preflight" class="primary" onclick="preflightFeishuMigration()">创建安全预检任务</button><p id="fm-form-note" class="muted"></p></div>${details.map(x=>renderFeishuTask(x,readiness)).join('')}`;updateFeishuFormState()}
function renderFeishuTask(detail,readiness){const t=detail.task,r=detail.report,startable=['awaiting_readonly_authorization','awaiting_server_configuration','connection_failed','authorization_failed','awaiting_private_storage'].includes(t.status),canRun=t.sourceMode==='official_readonly'&&t.rootLinkValidated&&startable&&readiness.canRunOfficialMigration;let actionNote='该任务已进入审核、已断开或正在执行，不能重复迁入。';if(t.sourceMode==='export_package')actionNote='离线任务等待生产私有上传通道，不使用飞书连接。';else if(startable&&!readiness.privateStorageConfigured)actionNote='先配置私有附件存储并重启服务。';else if(startable&&readiness.connection.status!=='connection_success')actionNote='先完成服务端配置并测试连接。';else if(canRun)actionNote='可运行；首次读取将验证目标 Wiki 资源读权。';return `<div class="panel"><div class="panel-head"><h2>${esc(t.id)} · <span class="pill">${esc(display(t.status))}</span></h2><span class="muted">持续同步：否</span></div>${t.errorCategory?`<div class="warning">上次失败分类：${esc(display(t.errorCategory))}</div>`:''}<div class="cards"><div class="card"><span>总数</span><strong>${r.total}</strong></div><div class="card"><span>待审核</span><strong>${r.pendingReview}</strong></div><div class="card"><span>已迁入</span><strong>${r.migrated}</strong></div><div class="card"><span>已跳过</span><strong>${r.skipped}</strong></div><div class="card"><span>异常 / 重试</span><strong>${r.failed}</strong></div><div class="card"><span>需人工分类</span><strong>${r.needsClassification}</strong></div><div class="card"><span>附件待处理</span><strong>${r.attachmentPending}</strong></div></div><h3>目录树预检</h3>${detail.directoryTree.length?`<div class="tree-list">${detail.directoryTree.map(x=>`<div><b>${esc(x.label)}</b><span>${x.itemCount??'—'} 项</span></div>`).join('')}</div>`:'<div class="hint">尚未安全读取目录；运行时会验证目标 Wiki 读权。</div>'}<h3>逐项状态</h3>${table(detail.items)}<div class="task-actions"><button class="primary" ${canRun?'':'disabled'} onclick="startFeishuMigration('${t.id}')">运行一次性迁入</button><button class="secondary" ${r.failed?'':'disabled'} onclick="retryFeishuMigration('${t.id}')">重试失败项</button><button class="secondary" ${t.sourceDisconnected?'disabled':''} onclick="disconnectFeishuMigration('${t.id}')">彻底断开来源</button></div><p class="muted">${esc(actionNote)}</p></div>`}
async function testFeishuConnection(){try{await requestJson('/api/admin/feishu-connection/test',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});await load('feishu-onetime')}catch(error){alert(error.message)}}
async function startFeishuMigration(id){try{await requestJson(`/api/admin/feishu-migrations/${id}/start`,{method:'POST'});await load('feishu-onetime')}catch(error){alert(error.message);await load('feishu-onetime')}}
async function preflightFeishuMigration(){try{const sourceMode=document.querySelector('#fm-source').value;const payload={rootUrl:document.querySelector('#fm-root').value,sourceMode,scope:document.querySelector('#fm-scope').value,classificationStrategy:document.querySelector('#fm-strategy').value};if(sourceMode==='export_package')delete payload.rootUrl;await requestJson('/api/admin/feishu-migrations/preflight',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});await load('feishu-onetime')}catch(error){alert(error.message)}}
async function retryFeishuMigration(id){try{const result=await requestJson(`/api/admin/feishu-migrations/${id}/retry-failures`,{method:'POST'});alert(`已排队 ${result.retried} 个失败项；缺少来源时仍会等待重新授权或导出包。`);await load('feishu-onetime')}catch(error){alert(error.message)}}
async function disconnectFeishuMigration(id){try{await confirmedJson(`/api/admin/feishu-migrations/${id}/disconnect`,{method:'POST'},'feishu.disconnect','高风险操作：断开后会清除来源引用，已迁入自有内容保留。确认继续？');await load('feishu-onetime')}catch(error){if(error.message!=='已取消操作')alert(error.message)}}
function importItemCard(item){const notices=[...(item.errors||[]).map(x=>`<div class="error">${esc(x)}</div>`),...(item.warnings||[]).map(x=>`<div class="warning">${esc(x)}</div>`)].join('')||'<div class="ok">校验通过</div>';const publish=item.kind==='knowledge'&&item.status==='ready'&&item.data.destination==='knowledge_base'?`<button class="secondary" onclick="publishImport('${item.id}')">上架知识库</button>`:'';const directoryReview=item.kind==='voluntary_directory'&&item.status==='needs_human_review'?`<button class="secondary" onclick="submitDirectoryReview('${item.id}')">提交公开名册人工审核</button>`:'';const crmConflict=item.kind==='crm_verification'&&item.status==='error'?`<div class="hint"><b>逐行冲突选择（匿名演练）</b><p>可先采用匿名候选映射补齐会籍窗口并重新预检，或保留本行继续人工核对；不会改变最终会籍。</p><button class="secondary" onclick="useAnonymousCrmCandidate('${item.id}')">采用匿名候选 A 并复检</button><button class="secondary" onclick="document.querySelector('#edit-${item.id}').focus()">保留冲突，人工编辑</button></div>`:'';const editor=item.status==='published'?'<div class="ok">资料已上架；后续修改应进入知识库执行版本化更新。</div>':`${crmConflict}<textarea id="edit-${item.id}" class="json-input">${esc(JSON.stringify(item.data,null,2))}</textarea><button class="primary" onclick="correctImport('${item.id}')">保存修正并复检</button>${publish}${directoryReview}`;return `<div class="panel import-item"><h2>第 ${item.rowNumber} 行 · <span class="pill">${esc(display(item.status))}</span></h2>${notices}${editor}</div>`}
function spreadsheetSummary(payload){const sheet=payload.spreadsheet;if(!sheet)return '';const fields=(sheet.detectedStandardFields||[]).join('、')||'尚需确认映射';return `<div class="mapping-note"><b>已读取 ${payload.batch.totalRows} 行 · 异常 ${payload.batch.errorRows} 行 · ${esc(sheet.format.toUpperCase())} / ${esc(sheet.sheetName)}</b><span>标准字段映射：${esc(fields)}${sheet.needsMapping?'（存在未映射或不合规表头，需修正）':''}</span></div>`}
function renderImportResults(payload){document.querySelector('#import-result').innerHTML=`<div class="panel"><h2>批次 ${esc(payload.batch.id)}</h2>${spreadsheetSummary(payload)}<div class="hint">共 ${payload.batch.totalRows} 行，待复核 ${payload.batch.reviewRows||payload.batch.validRows||0} 行，排除 ${payload.batch.excludedRows||0} 行，异常 ${payload.batch.errorRows} 行。预检不会自动改变会籍、付款事实或公开名册。</div></div>${payload.items.map(importItemCard).join('')}`}
async function previewImport(kind){try{const paths={knowledge:'knowledge',crm_verification:'internal-crm',voluntary_directory:'voluntary-directory',shop_order_evidence:'wechat-shop-orders'},payload=kind==='knowledge'?{csv:document.querySelector('#csv-input').value}:await spreadsheetPayload(selectedWorkbenchFiles[kind]);renderImportResults(await requestJson(`/api/admin/imports/${paths[kind]}/preview`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}))}catch(error){alert(error.message)}}
async function correctImport(id){try{const changes=JSON.parse(document.querySelector(`#edit-${id}`).value);['destination','resourceType','phoneMasked','phonePresent','operatorNotePresent','paymentTimePresent','productNamePresent','productRuleStatus','netPositive','evidenceCandidate','determinesMembershipAlone','eligibleForReview','reviewStatus','crmSyncAllowed'].forEach(k=>delete changes[k]);const item=await requestJson(`/api/admin/import-items/${id}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({changes})});alert(['ready','needs_human_review'].includes(item.status)?'修正完成，复检通过或进入人工复核':`已保存，当前状态：${item.status}`);load('import-items')}catch(error){alert(`修正失败：${error.message}`)}}
function useAnonymousCrmCandidate(id){const editor=document.querySelector(`#edit-${id}`);try{const value=JSON.parse(editor.value);editor.value=JSON.stringify({...value,internal_member_ref:'anonymous-member-ref-a',crm_verification_status:'verified',membership_start:'2026-01-01',membership_end:'2027-01-01',group_status:'in_group',migration_status:'ready'},null,2);correctImport(id)}catch(error){alert(`匿名候选映射失败：${error.message}`)}}
async function publishImport(id){try{const item=await confirmedJson(`/api/admin/import-items/${id}/publish`,{method:'POST'},'resource.publish','发布后资料将按权限向会员开放。请确认来源、版权和访问级别均已复核。');alert(`已上架：${item.title}`);load('resources')}catch(error){if(error.message!=='已取消操作')alert(error.message)}}
async function submitDirectoryReview(id){try{await requestJson(`/api/admin/import-items/${id}/submit-directory-review`,{method:'POST'});alert('已提交人工审核；不会从 CRM 或订单自动公开。');load('directory-profiles')}catch(error){alert(error.message)}}
function renderReviewQueue(kind,rows){if(!rows.length)return '<div class="hint">当前队列为空。</div>';return `<div class="hint">共 ${rows.length} 条记录。队列状态彼此独立，审核不会跨域修改会籍或公开资料。</div>`+rows.map(row=>{if(kind==='public')return `<div class="panel"><h2>${esc(row.id)} · <span class="pill">${esc(display(row.status))}</span></h2><pre class="review-data">${esc(JSON.stringify(row.proposedProfile,null,2))}</pre><button class="primary" onclick="reviewPublic('${row.id}','start_review')">开始审核</button><button class="secondary" onclick="reviewPublic('${row.id}','approved')">审核发布</button><button class="secondary" onclick="reviewPublic('${row.id}','returned_for_revision')">退回补充</button></div>`;return `<div class="panel"><h2>${esc(row.id)} · <span class="pill">${esc(display(row.status))}</span></h2><div class="hint">类型：${esc(row.mimeType)}；大小分级：${esc(row.sizeClass)}；仅展示安全元数据；演示文件已保存：${esc(row.artifactStored)}</div><button class="primary" onclick="reviewEmployment('${row.id}','start_review')">开始核验</button><button class="secondary" onclick="reviewEmployment('${row.id}','verified')">核验通过</button><button class="secondary" onclick="reviewEmployment('${row.id}','returned_for_revision')">退回补充</button><button class="secondary" onclick="reviewEmployment('${row.id}','rejected')">拒绝</button></div>`}).join('')}
function renderPaymentEvidence(rows){return `<div class="panel"><h2>人工补录付款证据</h2><div class="hint">只登记内部会员引用、时间和规则档位，不录入手机号、订单号、支付凭据或联系方式；补录后仍需独立复核，不能单独激活会籍。</div><div class="form-grid"><label>内部会员引用<input id="manual-pay-user" class="form-input" placeholder="例如 u-active"></label><label>发生时间<input id="manual-pay-time" class="form-input" type="datetime-local"></label><label>金额规则档位<select id="manual-pay-band" class="form-input"><option value="standard">标准价</option><option value="dedicated_offer">专属价</option><option value="legacy_offer">历史规则</option><option value="manual_review">待人工确认</option></select></label></div><button class="primary" onclick="recordManualPayment()">登记为待复核证据</button></div>${table(rows)}<div class="panel"><h2>付款证据复核</h2>${rows.filter(x=>x.evidenceStatus==='needs_review').map(x=>`<div class="bulk-bar"><b>${esc(x.id)}</b><span class="pill">${esc(display(x.refundStatus))}</span><button class="secondary" onclick="reviewPayment('${x.id}','verified','${x.refundStatus}')">确认有效</button><button class="secondary danger" onclick="reviewPayment('${x.id}','excluded','${x.refundStatus}')">排除证据</button></div>`).join('')||'<div class="hint">当前无待复核付款证据。</div>'}</div>`}
async function recordManualPayment(){try{const value=document.querySelector('#manual-pay-time').value;if(!value)throw new Error('请填写发生时间');await confirmedJson('/api/admin/payment-evidence/manual',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({userId:document.querySelector('#manual-pay-user').value,occurredAt:new Date(value).toISOString(),amountBand:document.querySelector('#manual-pay-band').value,productRuleStatus:'manual_review'})},'payment.manual_record','确认登记这条人工付款证据？它不会单独改变会籍。');load('payment-evidence')}catch(e){if(e.message!=='已取消操作')alert(e.message)}}
async function reviewPayment(id,decision,refundStatus){try{await confirmedJson(`/api/admin/payment-evidence/${id}/review`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({decision,refundStatus})},'payment.review','确认付款/退款线索结论？它只用于匹配和补全 CRM，不能单独激活会员；最终仍以大群状态和运营判断为准。');load('payment-evidence')}catch(e){if(e.message!=='已取消操作')alert(e.message)}}
function renderRenewalOffers(rows){return rows.map(x=>`<div class="panel"><h2>${esc(x.id)} · ${esc(x.userId)}</h2><div class="form-grid"><label>标准价（分）<input id="std-${x.id}" class="form-input" type="number" value="${x.standardPriceCents}"></label><label>专属价（分）<input id="offer-${x.id}" class="form-input" type="number" value="${x.offeredPriceCents}"></label><label>优惠理由<input id="reason-${x.id}" class="form-input" value="${esc(x.discountReason)}"></label></div><p class="muted">适用规则：${esc(JSON.stringify(x.eligibilityRule))}</p><button class="primary" onclick="updateRenewal('${x.id}')">保存续费方案</button></div>`).join('')||'<div class="hint">暂无续费方案。</div>'}
async function updateRenewal(id){try{await confirmedJson(`/api/admin/renewal-offers/${id}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({standardPriceCents:Number(document.querySelector(`#std-${id}`).value),offeredPriceCents:Number(document.querySelector(`#offer-${id}`).value),discountReason:document.querySelector(`#reason-${id}`).value})},'renewal.update','确认更新该会员的标准价、专属价和优惠理由？');load('renewal-offers')}catch(e){if(e.message!=='已取消操作')alert(e.message)}}
function renderNotificationJobs(rows){const retryable=rows.filter(x=>['retry_pending','template_pending'].includes(x.status));return `<div class="panel"><h2>通知异常处理</h2><div class="hint">演示环境只改变内部任务状态，不调用微信订阅消息。生产发送仍需模板、用户授权和真实回执。</div>${retryable.map(x=>`<div class="bulk-bar"><input class="bulk-select" type="checkbox" value="${esc(x.id)}"><b>${esc(x.id)}</b><span>${esc(display(x.trigger))}</span><span class="pill">${esc(display(x.status))}</span><button class="secondary" onclick="retryNotification('${x.id}')">加入重试队列</button></div>`).join('')||'<div class="hint">当前无重试任务。</div>'}${retryable.length?'<button class="secondary" onclick="bulkAction(\'notification_retry\')">批量加入重试</button>':''}</div>${table(rows)}`}
async function retryNotification(id){try{await requestJson(`/api/admin/notification-jobs/${id}/retry`,{method:'POST'});load('notification-jobs')}catch(e){alert(e.message)}}
async function bulkAction(action){try{const ids=[...document.querySelectorAll('.bulk-select:checked')].map(x=>x.value);if(!ids.length)throw new Error('请先选择记录');const preview=await requestJson('/api/admin/bulk-actions/preview',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,ids})});if(!confirm(`批量预检：可处理 ${preview.eligible} 条，拒绝 ${preview.rejected} 条。确认执行？`))return;await confirmedJson('/api/admin/bulk-actions/execute',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,ids})},'bulk.execute','再次确认批量执行？操作会记录审计并限制最多 100 条。');load(currentView)}catch(e){if(e.message!=='已取消操作')alert(e.message)}}
function renderDemandQueue(rows){return `<div class="hint">人工终审只处理匿名卡片与安全状态；公司名、交易细节和高敏材料不得从此页面发布。</div>${rows.map(x=>`<div class="panel"><h2>${esc(x.anonymousTitle)} · <span class="pill">${esc(display(x.humanReviewStatus))}</span></h2><p>${esc(x.anonymousSummary)}</p><p class="muted">类型：${esc(x.type)}；AI：${esc(display(x.aiReviewStatus))}；披露：${esc(display(x.disclosureLevel))}</p>${x.humanReviewStatus==='pending'?`<button class="primary" onclick="reviewDemand('${x.id}','approved')">终审通过</button><button class="secondary" onclick="reviewDemand('${x.id}','approved_with_notes')">附条件通过</button><button class="secondary danger" onclick="reviewDemand('${x.id}','rejected')">拒绝</button>`:''}</div>`).join('')}`}
async function reviewDemand(id,decision){try{await confirmedJson(`/api/admin/demands/${id}/human-review`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({decision})},'demand.finalize','确认需求人工终审结论？此操作不会公开公司名、交易细节、联系方式或高敏材料。');load('demands')}catch(e){if(e.message!=='已取消操作')alert(e.message)}}
function renderApplications(rows){return `<div class="hint">Agent/运营分发只更新筛选结论；联系方式和商业敏感信息仍须需求方确认后定向披露。</div>${rows.map(x=>`<div class="panel"><h2>${esc(x.id)} · <span class="pill">${esc(display(x.agentReviewStatus))}</span></h2><p>${esc(x.reason)}</p>${x.agentReviewStatus==='pending'?`<button class="primary" onclick="dispatchApplication('${x.id}','shortlist')">入选并转需求方</button><button class="secondary danger" onclick="dispatchApplication('${x.id}','decline')">不入选</button>`:''}</div>`).join('')}`}
async function dispatchApplication(id,decision){try{await confirmedJson(`/api/admin/applications/${id}/agent-dispatch`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({decision})},'application.dispatch','确认 Agent/运营筛选结论？此步骤不会披露联系方式。');load('applications')}catch(e){if(e.message!=='已取消操作')alert(e.message)}}
const paymentImportConfigs={wechat_shop_order:{title:'① 微信小店订单 Excel',template:'wechat-shop-orders',fields:'收件人姓名、订单发货时间、收件人手机号、商品价格',note:'整表导出可直接上传；只读取这四类匹配线索，其他订单列自动忽略。'},wechat_merchant_receipt:{title:'② 微信经营账户 / 商户号支付小票 Excel',template:'wechat-merchant-receipts',fields:'付款人姓名、支付时间、付款人手机号、支付金额',note:'只读取商户支付匹配所需的最简字段，其他列自动忽略。'},manual_transfer:{title:'③ 手动转账维护 Excel',template:'manual-transfers',fields:'成员姓名、转账时间、手机号、转账金额',note:'只读取人工转账匹配所需的最简字段，其他列自动忽略。'}};
const selectedPaymentImportFiles={};
function paymentPriceRules(source){if(source!=='wechat_shop_order')return '';return `<div class="hint"><b>价格 → 会员身份规则（可选，可随时修改）</b><div class="form-grid"><label>A1轮股东价格（元）<input id="payment-a1-prices" class="form-input" placeholder="例如 1999；多个价格用逗号分隔"></label><label>A2轮股东价格（元）<input id="payment-a2-prices" class="form-input" placeholder="例如 2999；多个价格用逗号分隔"></label></div><span>未配置或未命中的价格只标为待人工归类，不会自动判断会员身份。</span></div>`}
function paymentImportCard(source,config){const multiple=source==='wechat_merchant_receipt',pickLabel=multiple?'选择多个 .xlsx / .csv，或一起拖放到这里':'选择 .xlsx 或 .csv，或拖放到这里',limit=multiple?'单文件 10MB / 10,000 行；整批最多 10 个文件、30MB / 30,000 行。':'常规订单整表无需拆分；安全硬上限 10MB、10,000 行。';return `<article class="panel payment-import-card"><h2>${config.title}</h2><p class="muted">读取字段：${config.fields}</p><div class="ok">${config.note}</div><div class="warning">只做会员匹配与 CRM 补全线索，不会直接激活会籍，也不会更新公开名册。</div>${paymentPriceRules(source)}<p><a class="download" href="/api/admin/import-templates/${config.template}.xlsx">下载 Excel 模板</a> · <a class="download" href="/api/admin/import-templates/${config.template}.csv">下载 CSV 模板</a></p><div class="local-drop" ondragover="event.preventDefault()" ondrop="dropPaymentImportFile(event,'${source}')" onclick="document.querySelector('#payment-file-${source}').click()"><b>${pickLabel}</b><span id="payment-file-state-${source}">${limit} 旧版 .xls 与宏文件不支持。</span><input id="payment-file-${source}" type="file" hidden accept=".csv,.xlsx" ${multiple?'multiple':''} onchange="selectPaymentImportFile('${source}',this.files)"></div><button id="payment-preview-${source}" class="primary" disabled onclick="previewPaymentImport('${source}')">运行预检</button></article>`}
function paymentImportPanel(){return `<section id="payment-import-panel" class="panel" hidden><div class="panel-head"><div><h2>导入付款记录</h2><p class="muted">三类来源都可直接读取 .xlsx 或 .csv，普通订单导出无需人工拆分。</p></div><button class="secondary" onclick="togglePaymentImportPanel()">收起</button></div><div class="hint">系统会读取首个有内容的可见工作表并逐行预检；仅在超过 10MB / 10,000 行安全硬上限，或发现宏、外链、隐藏批注、危险公式时才会阻止。预检不回显原始敏感值。</div><div class="queue-grid">${Object.entries(paymentImportConfigs).map(([source,config])=>paymentImportCard(source,config)).join('')}</div><div id="payment-import-result"></div></section>`}
function mountMemberPaymentImport(){const paymentStep=[...document.querySelectorAll('.queue-card')].find(card=>card.querySelector('h2')?.textContent.includes('三类付款线索')),grid=paymentStep?.closest('.queue-grid');if(!paymentStep||!grid)return;paymentStep.querySelectorAll('button').forEach(button=>button.remove());paymentStep.insertAdjacentHTML('beforeend','<button class="primary" onclick="togglePaymentImportPanel()">导入付款记录</button>');grid.insertAdjacentHTML('afterend',paymentImportPanel())}
function togglePaymentImportPanel(){const panel=document.querySelector('#payment-import-panel');if(!panel)return;panel.hidden=!panel.hidden;if(!panel.hidden)panel.scrollIntoView({behavior:'smooth',block:'start'})}
function selectPaymentImportFile(source,files){const picked=[...(files||[])],multiple=source==='wechat_merchant_receipt',state=document.querySelector(`#payment-file-state-${source}`),button=document.querySelector(`#payment-preview-${source}`);delete selectedPaymentImportFiles[source];button.disabled=true;if(!picked.length){state.textContent='尚未选择文件。';return}if(!multiple&&picked.length>1){state.textContent='该来源一次选择一个文件；商户号支付小票可多文件同批预检。';return}if(picked.length>10){state.textContent='未读取：单批最多选择 10 个文件。';return}const invalid=picked.some(file=>!['xlsx','csv'].includes((file.name.split('.').pop()||'').toLowerCase()));if(invalid){state.textContent='未读取：仅支持 .xlsx 和 .csv；旧版 .xls 与宏文件不支持。';return}if(picked.some(file=>file.size>10*1024*1024)){state.textContent='未读取：其中一个文件超过 10MB 安全硬上限。';return}const totalBytes=picked.reduce((sum,file)=>sum+file.size,0);if(totalBytes>30*1024*1024){state.textContent='未读取：整批超过 30MB，请分成两个批次。';return}selectedPaymentImportFiles[source]=picked;state.textContent=multiple?`已选 ${picked.length} 个文件（不回显文件名），合计 ${(totalBytes/1024/1024).toFixed(1)}MB；将作为同一批次预检。`:`已选择 ${(picked[0].name.split('.').pop()||'').toUpperCase()}（不回显文件名）；可直接预检整表。`;button.disabled=false}
function dropPaymentImportFile(event,source){event.preventDefault();event.stopPropagation();selectPaymentImportFile(source,event.dataTransfer?.files)}
function paymentSummaryMarkup(payload){const summary=payload.summary||{},shop=payload.paymentSource==='wechat_shop_order',roleCards=shop?`<div class="card"><span>价格待归类</span><strong>${summary.priceUnclassifiedRows||0}</strong></div><div class="card"><span>A1 / A2 候选</span><strong>${summary.a1CandidateRows||0} / ${summary.a2CandidateRows||0}</strong></div>`:`<div class="card"><span>金额线索</span><strong>${summary.priceClueRows||0}</strong></div>`;return `<div class="cards"><div class="card"><span>可匹配线索</span><strong>${summary.matchingCandidateRows||0}</strong></div><div class="card"><span>待人工核对</span><strong>${summary.needsManualRows||0}</strong></div><div class="card"><span>${shop?'发货时间线索':'发生时间线索'}</span><strong>${summary.groupEntryClueRows||0}</strong></div>${roleCards}<div class="card"><span>可能退款/售后</span><strong>${summary.possibleRefundRows||0}</strong></div></div><div class="hint">已识别：${esc((payload.recognizedFields||[]).join('、')||'尚未识别关键字段')}；自动忽略 ${payload.ignoredColumnCount||0} 个无关列。${shop?(payload.pricingRulesConfigured?'价格规则已用于生成候选。':'价格规则未配置，价格只进入人工归类。'):''} 姓名、手机号、价格、订单号和备注原值均不回显。</div>`}
function paymentBatchFileMarkup(payload){if(!Array.isArray(payload.files))return spreadsheetSummary(payload);return `<div class="hint"><b>已选 ${payload.selectedFileCount||0} 个文件</b> · 合格 ${payload.validFileCount||0} 个 · 异常 ${payload.errorFileCount||0} 个 · 已读取 ${payload.totalRows||0} 行。异常文件会单独标注，其他合格文件不会被丢弃。</div><div class="queue-grid">${payload.files.map(file=>file.status==='error'?`<div class="warning"><b>文件 ${file.fileIndex}</b><span>异常 ${esc(file.error?.code||'SPREADSHEET_INVALID')}：${esc(file.error?.message||'无法安全预检')}</span></div>`:`<div class="ok"><b>文件 ${file.fileIndex}</b><span>${esc(String(file.spreadsheet?.format||'').toUpperCase())} · ${file.spreadsheet?.rowCount||0} 行 · 待人工核对 ${file.summary?.needsManualRows||0} 行 · 忽略 ${file.ignoredColumnCount||0} 列</span></div>`).join('')}</div>`}
async function previewPaymentImport(source){try{const files=selectedPaymentImportFiles[source]||[];if(!files.length)throw new Error('请先选择文件');const multi=source==='wechat_merchant_receipt',input=multi?{paymentSource:source,files:await Promise.all(files.map(spreadsheetPayload))}:await spreadsheetPayload(files[0]);input.paymentSource=source;if(source==='wechat_shop_order')input.priceRoleRules={a1:document.querySelector('#payment-a1-prices')?.value||'',a2:document.querySelector('#payment-a2-prices')?.value||''};const payload=await requestJson('/api/admin/imports/wechat-shop-orders/preview',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(input)}),label=paymentImportConfigs[source].title.replace(/^\S+\s*/,''),result=document.querySelector('#payment-import-result');result.innerHTML=`<div class="panel"><h2>${esc(label)} · 汇总预检完成</h2>${paymentBatchFileMarkup(payload)}${paymentSummaryMarkup(payload)}<div class="ok">订单只生成 CRM 匹配与身份候选，不会自动激活会籍；大群状态仍是最终准则，也不会生成公开名册。</div></div>`;result.scrollIntoView({behavior:'smooth',block:'start'})}catch(error){alert(`付款记录预检失败：${error.message}`)}}
function paymentClueMarkup(sources){return `<span class="pill">小店 ${sources.wechatShop?'有线索':'无'}</span><span class="pill">商户号 ${sources.wechatMerchant?'有线索':'无'}</span><span class="pill">手动转账 ${sources.manualTransfer?'有线索':'无'}</span>`}
function memberCrmCard(row){const editable=row.id.startsWith('u-'),decision=row.temporarilyActive?'待续费跟进 / 仍暂时有效':display(row.operatorDecision),missing=row.missingItems?.length?row.missingItems.join('、'):'无待补项';return `<article class="panel member-crm-card" data-member-search="${esc(`${row.alias} ${row.id} ${row.groupLabel} ${missing}`.toLowerCase())}"><div class="panel-head"><div><h2>${esc(row.alias)} · <span class="pill">${esc(decision)}</span></h2><p class="muted">匹配：${esc(display(row.matchStatus))} · CRM：${esc(display(row.crmCompletionStatus))}</p></div><span class="pill">${esc(display(row.groupStatus))}</span></div><div class="migration-counts"><span>微信群标签：${esc(row.groupLabel)}</span><span>标签有效期：${row.groupLabelExpiry?esc(String(row.groupLabelExpiry).slice(0,10)):'待确认'}</span><span>OCR：${esc(display(row.ocrStatus))}</span></div><div class="tag-candidates">${paymentClueMarkup(row.paymentSources)}</div><div class="${row.missingItems?.length?'warning':'ok'}">待人工补充：${esc(missing)}</div><details><summary>查看运营确认项</summary><div class="form-grid"><label>是否仍在大群<select id="group-${row.id}" class="form-input" ${editable?'':'disabled'}><option value="in_group" ${row.groupStatus==='in_group'?'selected':''}>仍在大群（当前门禁通过）</option><option value="left" ${row.groupStatus==='left'?'selected':''}>已退群</option><option value="removed" ${row.groupStatus==='removed'?'selected':''}>已移出</option><option value="unknown" ${row.groupStatus==='unknown'?'selected':''}>待确认</option></select></label><label>续费跟进<select id="renewal-${row.id}" class="form-input" ${editable?'':'disabled'}><option value="not_notified" ${row.renewalNoticeStatus==='not_notified'?'selected':''}>尚未通知续费</option><option value="follow_up_pending" ${row.renewalNoticeStatus==='follow_up_pending'?'selected':''}>已列入跟进</option><option value="notified_overdue" ${row.renewalNoticeStatus==='notified_overdue'?'selected':''}>已通知且逾期</option></select></label></div>${editable?`<button class="primary" onclick="updateGroupStatus('${row.id}')">保存运营判断</button>`:'<div class="hint">此 OCR 行尚未匹配成员，先处理匹配冲突，不能直接改变会籍。</div>'}<p class="muted">保存只生成内部运营判断，不改变公开名册；三类付款均只是完善 CRM 的线索。</p></details></article>`}
function filterMemberCrm(value){const query=String(value||'').trim().toLowerCase();document.querySelectorAll('.member-crm-card').forEach(card=>card.hidden=query&&!card.dataset.memberSearch.includes(query))}
function loadAnonymousGroupOcr(){sessionStorage.setItem('venture-group-ocr-rehearsal','loaded');load('members')}
function renderMembers(rows){const ocrLoaded=sessionStorage.getItem('venture-group-ocr-rehearsal')==='loaded',unmatched=rows.filter(x=>x.matchStatus==='unmatched').length,followUp=rows.filter(x=>x.temporarilyActive).length;return `<div class="panel"><div class="panel-head"><div><h2>会员 CRM 库</h2><p class="muted">各种导入只作为 CRM 来源，最终由运营确认；是否仍在大群是当前最终门禁。</p></div><span class="pill">匿名本地演示</span></div><div class="migration-master-phases">导入来源 → 会员 CRM → 自动匹配 → 人工补全 → 运营确认</div><div class="warning">群标签到期但成员仍在大群、且尚未通知续费时，显示“待续费跟进 / 仍暂时有效”，不会自动标成失效。</div></div><div class="queue-grid"><div class="queue-card"><h2>1. 群成员与群标签</h2><strong>OCR 待确认</strong><p class="muted">只产生标签、日期和匹配候选，不能直接改会籍。</p><button class="secondary" onclick="loadAnonymousGroupOcr()">${ocrLoaded?'重新载入匿名 OCR 样本':'载入匿名 OCR 样本'}</button></div><div class="queue-card"><h2>2. 三类付款线索</h2><strong>小店 · 商户号 · 手动转账</strong><p class="muted">用于匹配与补全 CRM，任何一类都不能单独激活会员。</p><button class="secondary" onclick="load('shop-order-import')">查看匿名导入预检</button><button class="secondary" onclick="load('payment-evidence')">手工维护线索</button></div><div class="queue-card"><h2>3. 匹配与冲突</h2><strong>${unmatched}</strong><p class="muted">未匹配项必须逐行人工确认。</p><button class="secondary" onclick="load('import-items')">处理冲突</button></div><div class="queue-card"><h2>4. CRM 补全</h2><strong>${rows.filter(x=>x.missingItems?.length).length}</strong><p class="muted">补群状态、标签日期和缺失来源。</p><button class="primary" onclick="openMemberSpreadsheetImport('crm_verification')">导入 CRM Excel</button><button class="secondary" onclick="load('crm-verifications')">手工补充</button></div><div class="queue-card"><h2>5. 运营确认</h2><strong>${followUp}</strong><p class="muted">待续费跟进但仍暂时有效。</p></div></div><div class="panel"><div class="panel-head"><div><h2>成员列表</h2><p class="muted">仅后台可见；会员端不会收到群标签、付款线索、CRM 或运营判断。</p></div><input class="form-input" aria-label="搜索会员 CRM" placeholder="搜索匿名别名、标签或待补项" oninput="filterMemberCrm(this.value)"></div></div>${rows.map(memberCrmCard).join('')}<div class="panel"><h2>公开名册是独立队列</h2><p>公开名册只接受成员自愿同意并经人工审批的资料，不能从 CRM、付款或群标签自动生成。</p><button class="primary" onclick="openMemberSpreadsheetImport('voluntary_directory')">导入自愿名册 Excel</button><button class="secondary" onclick="load('directory-profiles')">进入公开名册</button></div>`}
async function updateGroupStatus(id){try{await confirmedJson(`/api/admin/members/${id}/group-status`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({groupStatus:document.querySelector(`#group-${id}`).value,renewalNoticeStatus:document.querySelector(`#renewal-${id}`).value})},'membership.group_status','确认保存大群状态与续费跟进判断？这不会改变公开名册，付款线索也不会单独激活会籍。');load('members')}catch(e){if(e.message!=='已取消操作')alert(e.message)}}
function renderCrm(rows){return `<div class="hint">内部 CRM 仅显示核验状态、到期日、群状态和在职核验子状态；不显示手机号、运营备注、付款凭据或名片内容。</div>${rows.map(x=>`<div class="panel"><h2>${esc(x.id)} · ${esc(x.userId)}</h2><div class="form-grid"><label>CRM 核验<select id="crm-status-${x.id}" class="form-input"><option value="verified" ${x.verificationStatus==='verified'?'selected':''}>已核验</option><option value="needs_review" ${x.verificationStatus==='needs_review'?'selected':''}>待复核</option><option value="suspended" ${x.verificationStatus==='suspended'?'selected':''}>冻结</option><option value="rejected" ${x.verificationStatus==='rejected'?'selected':''}>拒绝</option></select></label><label>群状态<select id="crm-group-${x.id}" class="form-input"><option value="in_group" ${x.groupStatus==='in_group'?'selected':''}>群内</option><option value="left" ${x.groupStatus==='left'?'selected':''}>已退群</option><option value="removed" ${x.groupStatus==='removed'?'selected':''}>已移除</option><option value="unknown" ${x.groupStatus==='unknown'?'selected':''}>未知</option></select></label><label>会籍到期<input id="crm-end-${x.id}" class="form-input" type="datetime-local" value="${esc(String(x.membershipEnd||'').slice(0,16))}"></label></div><p class="muted">在职核验：${esc(display(x.employmentVerificationStatus))}</p><button class="primary" onclick="updateCrm('${x.id}')">保存并重算会籍</button></div>`).join('')}`}
async function updateCrm(id){try{const end=document.querySelector(`#crm-end-${id}`).value;await confirmedJson(`/api/admin/crm-verifications/${id}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({verificationStatus:document.querySelector(`#crm-status-${id}`).value,groupStatus:document.querySelector(`#crm-group-${id}`).value,membershipEnd:end?new Date(end).toISOString():undefined})},'membership.crm_update','确认更新内部 CRM 并重新计算最终会籍？付款证据和公开名册不会被改写。');load('crm-verifications')}catch(e){if(e.message!=='已取消操作')alert(e.message)}}
function renderResources(rows){return `<div class="hint">列表不展示飞书来源、外部链接、附件路径或存储键。发布前必须确认来源版权和访问级别。</div>${rows.map(x=>`<div class="panel"><h2>${esc(x.title)} · <span class="pill">${esc(display(x.status))}</span></h2><p>${esc(x.summary)}</p><p class="muted">类型：${esc(x.type)}；权限：${esc(display(x.accessLevel))}；来源审核：${esc(display(x.sourceStatus))}；迁移：${esc(display(x.migrationStatus))}</p>${x.status!=='published'?`<button class="primary" onclick="reviewResource('${x.id}','published')">审核发布</button>`:''}${x.status!=='archived'?`<button class="secondary" onclick="reviewResource('${x.id}','archived')">归档</button>`:''}</div>`).join('')}`}
async function reviewResource(id,status){try{const options={method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({status})};if(status==='published')await confirmedJson(`/api/admin/resources/${id}/review`,options,'resource.publish','确认来源、版权、资料内容和会员访问级别均已审核？');else await requestJson(`/api/admin/resources/${id}/review`,options);load('resources')}catch(e){if(e.message!=='已取消操作')alert(e.message)}}
function renderActivities(rows){return `<div class="hint">线上报名仅登记和接收通知，不保证腾讯会议席位；特邀链接仍由服务端按有效会籍、报名和时间窗门禁。</div>${rows.map(x=>`<div class="panel"><h2>${esc(x.title)} · <span class="pill">${esc(display(x.status))}</span></h2><p class="muted">${esc(display(x.format))} · ${esc(x.city||'线上')} · ${esc(x.startsAt)} · 容量 ${esc(x.capacity)}</p>${x.status==='draft'?`<button class="primary" onclick="updateActivity('${x.id}','registration_open')">开放报名</button>`:''}${!['ended','cancelled'].includes(x.status)?`<button class="secondary" onclick="updateActivity('${x.id}','ended')">标记结束</button><button class="secondary danger" onclick="updateActivity('${x.id}','cancelled')">取消活动</button>`:''}</div>`).join('')}`}
async function updateActivity(id,status){try{const options={method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({status,reasonCode:status==='cancelled'?'other':undefined})};if(status==='cancelled')await confirmedJson(`/api/admin/activities/${id}/status`,options,'activity.cancel','确认取消活动？系统会生成取消通知任务，但演示环境不会真实发送。');else await requestJson(`/api/admin/activities/${id}/status`,options);load('activities')}catch(e){if(e.message!=='已取消操作')alert(e.message)}}
async function reviewPublic(id,decision){try{const options={method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({decision,reasonCode:decision==='returned_for_revision'?'needs_clarification':undefined})};if(decision==='approved')await confirmedJson(`/api/admin/public-profile-updates/${id}/review`,options,'directory.publish','确认已核验公开同意、展示字段和联系方式保护？发布后将进入会员名册。');else await requestJson(`/api/admin/public-profile-updates/${id}/review`,options);load('public-profile-updates')}catch(e){if(e.message!=='已取消操作')alert(e.message)}}
async function reviewEmployment(id,decision){try{const options={method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({decision,reasonCode:decision==='returned_for_revision'?'needs_new_artifact':undefined})};if(['verified','rejected'].includes(decision))await confirmedJson(`/api/admin/employment-verifications/${id}/review`,options,'employment.finalize','确认完成在职材料核验？结论仅更新 CRM 核验子状态，不改变会籍或公开资料。');else await requestJson(`/api/admin/employment-verifications/${id}/review`,options);load('employment-verifications')}catch(e){if(e.message!=='已取消操作')alert(e.message)}}

async function renderDashboard(){const data=await requestJson('/api/admin/dashboard'),names={members:'会员档案',activeMembers:'有效会员',nearExpiryMembers:'临期会员',pendingMembershipReviews:'会籍待复核',publicProfiles:'公开名册',pendingProfileReviews:'资料待审核',pendingEmploymentReviews:'在职核验队列',paymentReviews:'付款待复核',demandReviews:'需求待终审',dispatchReviews:'申请待分发',demands:'需求',applications:'需求申请',activities:'活动',resources:'资料',importBatches:'导入批次'};content.innerHTML=`<div class="panel local-import-hero"><div class="panel-head"><div><h2>从电脑导入资料</h2><p class="muted">资料迁入首选路径 · 上传后统一进入待审核区</p></div><button class="primary" onclick="load('local-materials')">进入导入工作台</button></div></div><div class="hint">业务能力按模块组织；所有人物、组织和记录均为虚构匿名演示数据。当前角色权限由服务端逐请求校验。</div><div class="cards">${Object.entries(data.metrics).filter(([k])=>names[k]).map(([k,v])=>`<div class="card"><span>${names[k]}</span><strong>${v}</strong></div>`).join('')}</div><div class="panel"><h2>需求覆盖</h2>${table(data.requirementCoverage)}</div>`}
async function renderTodo(){const [members,updates,employment,items,notifications,demands,applications]=await Promise.all(['members','public-profile-updates','employment-verifications','import-items','notification-jobs','demands','applications'].map(x=>requestJson(`/api/admin/${x}`)));const queues=[['会籍待复核',members.filter(x=>x.currentMembershipStatus!=='active').length,'members'],['公开资料待审核',updates.filter(x=>['submitted','pending_review'].includes(x.status)).length,'public-profile-updates'],['在职核验待处理',employment.filter(x=>['submitted','pending_review'].includes(x.status)).length,'employment-verifications'],['导入异常待修正',items.filter(x=>x.status==='error').length,'import-items'],['通知重试 / 待配置',notifications.filter(x=>['retry_pending','template_pending'].includes(x.status)).length,'notification-jobs'],['需求待终审',demands.filter(x=>x.humanReviewStatus==='pending').length,'demands'],['申请待分发',applications.filter(x=>['submitted','pending'].includes(x.status)||x.agentReviewStatus==='pending').length,'applications']];content.innerHTML=`<div class="queue-grid">${queues.map(([name,count,target])=>`<div class="queue-card"><h2>${name}</h2><strong>${count}</strong><br><button class="secondary" onclick="load('${target}')">进入处理</button></div>`).join('')}</div>`}
async function renderRisks(){const [members,items,notifications,resources]=await Promise.all(['members','import-items','notification-jobs','resources'].map(x=>requestJson(`/api/admin/${x}`)));const risks=[{title:'临期会员提醒',count:members.filter(x=>x.currentMembershipStatus==='active'&&new Date(x.endsAt)-Date.now()<30*86400000).length,note:'建议进入会员模块核对续费方案。',target:'renewal-offers'},{title:'导入安全异常',count:items.filter(x=>x.status==='error').length,note:'异常行不会自动改变会籍或公开名册。',target:'import-items'},{title:'通知发送风险',count:notifications.filter(x=>['retry_pending','template_pending'].includes(x.status)).length,note:'演示环境不调用真实订阅消息。',target:'notification-jobs'},{title:'资料来源待复核',count:resources.filter(x=>x.sourceStatus==='needs_rights_review'||x.migrationStatus==='needs_review').length,note:'版权或来源未确认前不可发布。',target:'resources'}];content.innerHTML=`<div class="queue-grid">${risks.map(x=>`<div class="queue-card"><h2>${x.title}</h2><strong>${x.count}</strong><p class="muted">${x.note}</p><button class="secondary" onclick="load('${x.target}')">查看</button></div>`).join('')}</div>`}
const migrationLaneConfigs=[
  {key:'materials',title:'本地资料',kinds:[],target:'local-materials',finalLabel:'人工审核后发布',boundary:'上传后默认待审核；标签可改。关闭下载不影响受控查看，文件在线预览能力仍待配置。'},
  {key:'crm',title:'会员 CRM',kinds:['crm_verification'],target:'crm-import',finalLabel:'独立物化到 CRM 私有域',boundary:'只核验 CRM、会籍窗口与群状态；缺项或冲突进入人工复核。'},
  {key:'payment',title:'付款证据',kinds:['shop_order_evidence'],target:'shop-order-import',finalLabel:'独立物化为付款证据',boundary:'订单只形成证据候选；退款或产品规则异常不放行，单笔订单不激活会籍。'},
  {key:'directory',title:'自愿公开名册',kinds:['voluntary_directory'],target:'voluntary-directory-import',finalLabel:'独立审批后公开',boundary:'必须 consent=granted 且人工批准；不从 CRM、付款或会籍自动生成。'}
];
function migrationLaneState(config,batches,items,local){const laneBatches=config.key==='materials'?(local.batches||[]):batches.filter(batch=>config.kinds.includes(batch.kind)),laneItems=config.key==='materials'?(local.items||[]):items.filter(item=>config.kinds.includes(item.kind)),errors=laneItems.filter(item=>item.status==='error').length,review=laneItems.filter(item=>['pending_review','needs_human_review','needs_classification','submitted_for_directory_review','ready'].includes(item.status)).length,completed=laneItems.filter(item=>['published','approved','materialized'].includes(item.status)).length,total=laneItems.length,hasBatch=laneBatches.length>0,phases=[hasBatch||total?'done':'current',hasBatch?'done':'waiting',errors?'blocked':hasBatch?'done':'waiting',review||completed?'current':'waiting',completed?'done':'waiting'];return {...config,batches:laneBatches.length,total,errors,review,completed,phases,progress:completed?100:review?72:hasBatch?(errors?38:52):0}}
function migrationPhaseMarkup(lane){const names=['上传 / 建批次','预检与字段映射','冲突处理','人工审核','发布 / 分域物化'];return `<div class="migration-phases">${names.map((name,index)=>`<span class="phase ${lane.phases[index]}"><i>${index+1}</i>${name}</span>`).join('')}</div>`}
function migrationLaneCard(lane){return `<div class="panel migration-lane"><div class="panel-head"><div><h2>${lane.title}</h2><p class="muted">${lane.boundary}</p></div><button class="primary" onclick="load('${lane.target}')">进入此流程</button></div>${migrationPhaseMarkup(lane)}<div class="migration-progress"><span style="width:${lane.progress}%"></span></div><div class="migration-counts"><b>批次 ${lane.batches}</b><span>条目 ${lane.total}</span><span class="${lane.errors?'danger-text':''}">异常 ${lane.errors}</span><span>待审核 ${lane.review}</span><span>已完成 ${lane.completed}</span></div><div class="hint">最终动作：${lane.finalLabel}。异常项先进入“异常修正”，保存后会重新运行同一套校验。</div></div>`}
function rehearsalActive(){return sessionStorage.getItem('venture-migration-rehearsal')==='active'}
function startMigrationRehearsal(){sessionStorage.setItem('venture-migration-rehearsal','active');renderMigrationCenter()}
function rollbackMigrationRehearsal(){sessionStorage.removeItem('venture-migration-rehearsal');renderMigrationCenter()}
async function renderMigrationCenter(){const [local,batches,items]=await Promise.all([requestJson('/api/admin/local-imports'),requestJson('/api/admin/import-batches'),requestJson('/api/admin/import-items')]),lanes=migrationLaneConfigs.map(config=>migrationLaneState(config,batches,items,local)),errors=lanes.reduce((sum,lane)=>sum+lane.errors,0),pending=lanes.reduce((sum,lane)=>sum+lane.review,0),rehearsing=rehearsalActive();content.innerHTML=`<div class="panel migration-overview"><div class="panel-head"><div><h2>统一迁移工作流</h2><p class="muted">先用匿名副本演练，再逐域预检、修正和人工审核；当前页面不连接真实持久化。</p></div><span class="pill">${rehearsing?'匿名演练中':'准备模式'}</span></div><div class="migration-master-phases">准备模板 → 上传 / 建批次 → 预检映射 → 冲突修正 → 人工审核 → 发布或分域物化</div><div class="warning">四个事实域互不自动同步。公开名册不由 CRM/付款产生；订单不直接激活会籍；资料始终先进入待审核。</div><div class="migration-summary"><div><b>${lanes.reduce((sum,lane)=>sum+lane.batches,0)}</b><span>当前批次</span></div><div><b>${pending}</b><span>待人工审核</span></div><div><b>${errors}</b><span>安全异常</span></div></div><div class="rehearsal-bar"><div><b>可逆匿名演练</b><span>${rehearsing?'演练标记只保存在当前浏览器会话；不会修改批次或事实数据。':'用于熟悉步骤，不上传文件、不写业务记录。'}</span></div>${rehearsing?'<button class="secondary danger" onclick="rollbackMigrationRehearsal()">撤销本次演练</button>':'<button class="secondary" onclick="startMigrationRehearsal()">开始匿名演练</button>'}</div></div>${lanes.map(migrationLaneCard).join('')}<div class="panel"><h2>当前安全告警</h2><ul class="safety-list"><li>${errors?`有 ${errors} 个异常项，必须修正并复检；不会自动跳过。`:'未发现行级异常；仍需人工审核。'}</li><li>演示批次与审核状态在内存中，重启会丢失，不能视为正式迁移成功。</li><li>正式持久化、私有对象存储、真实后台身份未启用时，禁止导入真实会员、订单或资料。</li></ul><div class="bulk-bar"><button class="secondary" onclick="load('import-items')">处理异常项</button><button class="secondary" onclick="load('import-batches')">查看全部批次</button></div></div>`}
async function renderMembershipRehearsal(){const [members,decisions,payments,items]=await Promise.all(['members','membership-decisions','payment-evidence','import-items'].map(x=>requestJson(`/api/admin/${x}`))),crmItems=items.filter(x=>x.kind==='crm_verification'),conflicts=crmItems.filter(x=>x.status==='error').length;content.innerHTML=`<div class="panel"><div class="panel-head"><div><h2>会员数据确认演练</h2><p class="muted">按 CRM → 付款证据 → 群状态 → 最终判定逐域确认，任何缺项都保持待复核。</p></div><span class="pill">匿名离线</span></div><div class="migration-master-phases">1. CRM 分批预检 → 2. 逐行冲突处理 → 3. 付款证据复核 → 4. 群状态确认 → 5. 人工批准最终会籍</div><div class="warning">公开名册完全独立；订单只可成为付款证据候选，不能单独激活会籍。</div></div><div class="queue-grid"><div class="queue-card"><h2>CRM 导入行</h2><strong>${crmItems.length}</strong><p class="muted">冲突 ${conflicts} · 待复核 ${crmItems.filter(x=>x.status==='needs_human_review').length}</p><button class="secondary" onclick="load('import-items')">逐行处理</button></div><div class="queue-card"><h2>付款证据</h2><strong>${payments.length}</strong><button class="secondary" onclick="load('payment-evidence')">进入复核</button></div><div class="queue-card"><h2>最终判定</h2><strong>${decisions.length}</strong><p class="muted">有效 ${members.filter(x=>x.currentMembershipStatus==='active').length} · 待复核 ${members.filter(x=>x.currentMembershipStatus!=='active').length}</p><button class="secondary" onclick="load('members')">查看结果</button></div></div><div class="panel"><h2>最终会籍放行清单</h2><ul class="safety-list"><li>账号正常，且当前时间位于明确会籍窗口内。</li><li>CRM 已核验；会员匹配冲突已人工消解。</li><li>最近有效付款证据已复核并带发生时间；无退款冲突。</li><li>当前群状态必须为“群内”；unknown / 退群 / 移除均不放行。</li><li>最后由人工明确批准并记录判定；重算不会修改公开名册。</li></ul><div class="hint">本页只读取匿名演示状态；不能视为真实数据物化或云端持久化。</div></div>`}
async function renderMatchingRehearsal(){const [demands,reviews,applications]=await Promise.all(['demands','ai-reviews','applications'].map(x=>requestJson(`/api/admin/${x}`))),published=demands.filter(x=>x.status==='published').length,pending=demands.filter(x=>x.humanReviewStatus==='pending').length,dispatch=applications.filter(x=>x.agentReviewStatus==='pending').length;content.innerHTML=`<div class="panel"><div class="panel-head"><div><h2>需求撮合安全演练</h2><p class="muted">从成员描述需求到需求方决定是否释放联系方式，所有记录均为匿名样本。</p></div><span class="pill">规则提示 · 非真实 AI</span></div><div class="migration-master-phases">成员描述需求 → 规则提示 / AI 待配置 → 人工终审 → 匿名机会 → 成员申请 → Agent 二次分发 → 需求方决定</div><div class="warning">当前没有调用外部 AI；公司名、CRM、付款、交易细节和联系人不进入会员端响应。</div></div><div class="queue-grid"><div class="queue-card"><h2>待人工终审</h2><strong>${pending}</strong><button class="secondary" onclick="load('demands')">处理匿名卡片</button></div><div class="queue-card"><h2>已匿名发布</h2><strong>${published}</strong><p class="muted">含招聘、融资、并购、投资与招商样本</p></div><div class="queue-card"><h2>待 Agent 分发</h2><strong>${dispatch}</strong><button class="secondary" onclick="load('applications')">处理申请</button></div></div><div class="panel"><h2>按步骤验收</h2><ol class="safety-list"><li>会员端“Agent”提交不少于 20 字的匿名需求描述，只进入人工审核。</li><li>后台规则 / AI 初筛明确显示未配置，不虚称 AI 成功。</li><li>人工终审只审核匿名标题、摘要和类型；通过后才形成公开机会。</li><li>会员申请机会；Agent 只做入选或不入选，不披露联系人。</li><li>需求方决定同意受控介绍、拒绝或继续分发；接口仍不返回联系方式。</li></ol></div><div class="panel"><h2>演练样本覆盖</h2><div class="tag-candidates">${[...new Set(demands.map(x=>x.type))].map(x=>`<span class="pill">${esc(x)}</span>`).join('')}</div><p class="muted">初筛记录 ${reviews.length} 条；原始提示词、私密正文与外部模型结果均不展示。</p></div>`}
function renderGovernance(){content.innerHTML=`<div class="panel"><h2>四域数据隔离</h2><div class="hint">内部 CRM、公开名册、付款证据、会籍判定是相互独立的数据域。订单或 CRM 不得一键同步到公开名册；公开联系方式始终采用申请对接。</div></div><div class="panel"><h2>敏感数据原则</h2><p>会员端不返回 CRM、付款证据、联系方式、在职材料或需求高敏感字段。演示环境不保存真实附件、会议链接或外部凭据。</p><p class="muted">完整规则文件：docs/data-governance-and-matching.md</p></div>`}
async function renderReleaseChecks(){const readiness=await requestJson('/api/admin/operations-readiness'),env=readiness.environment;content.innerHTML=`<div class="queue-grid"><div class="queue-card"><h2>本地演示</h2><strong>正常</strong><p class="muted">匿名演示数据：${env.demoData?'是':'否'}；外部发送：${env.externalDelivery?'已接入':'未接入'}。</p></div><div class="queue-card"><h2>生产发布预检</h2><strong>未放行</strong><p class="muted">持久化数据库、生产身份、对象存储与真实外部能力尚未全部验收。</p></div></div><div class="panel"><h2>上线准备矩阵</h2>${table(readiness.checks)}</div><div class="panel"><h2>真实账号验收</h2><div class="hint">发布前需在微信开发者工具与真机核验 AppID、公司主体、服务器域名、隐私与权限、登录、支付、订阅消息、私有存储和腾讯会议配置。不得把演示身份头、测试 API、Secret 或外部来源路径带入生产。</div></div>`}

async function loadView(key){try{if(key==='dashboard')return renderDashboard();if(key==='todo')return renderTodo();if(key==='risks')return renderRisks();if(key==='migration-center')return renderMigrationCenter();if(key==='governance')return renderGovernance();if(key==='release-checks')return renderReleaseChecks();if(key==='feishu-onetime')return renderFeishuMigration();if(key==='activity-archives'){const rows=(await requestJson('/api/admin/resources')).filter(x=>x.type==='meeting_replay');content.innerHTML=table(rows);return}if(['knowledge-import','crm-import','voluntary-directory-import','shop-order-import'].includes(key))return renderImportWorkbench({'knowledge-import':'knowledge','crm-import':'crm_verification','voluntary-directory-import':'voluntary_directory','shop-order-import':'shop_order_evidence'}[key]);const data=await requestJson(`/api/admin/${key}`);if(key==='members')content.innerHTML=renderMembers(data);else if(key==='crm-verifications')content.innerHTML=renderCrm(data);else if(key==='resources')content.innerHTML=renderResources(data);else if(key==='activities')content.innerHTML=renderActivities(data);else if(key==='import-items')content.innerHTML=data.length?data.map(importItemCard).join(''):'<div class="hint">暂无导入工作项。</div>';else if(key==='public-profile-updates')content.innerHTML=renderReviewQueue('public',data);else if(key==='employment-verifications')content.innerHTML=renderReviewQueue('employment',data);else if(key==='payment-evidence')content.innerHTML=renderPaymentEvidence(data);else if(key==='renewal-offers')content.innerHTML=renderRenewalOffers(data);else if(key==='notification-jobs')content.innerHTML=renderNotificationJobs(data);else if(key==='demands')content.innerHTML=renderDemandQueue(data);else if(key==='applications')content.innerHTML=renderApplications(data);else content.innerHTML=table(data)}catch(error){content.innerHTML=`<div class="error">${esc(error.message)}</div>`}}
async function loadSession(){roleSelect.value=adminRole;const session=await requestJson('/api/admin/session');sessionPermissions=session.permissions;roleBadge.textContent=session.label;roleNote.textContent=session.note;refreshNavigationPermissions();roleSelect.onchange=async()=>{adminRole=roleSelect.value;sessionStorage.setItem('venture-admin-role',adminRole);try{await loadSession();await navigate('workbench','dashboard')}catch(e){alert(e.message)}}}
const baseUpdateFeishuFormState=updateFeishuFormState;
updateFeishuFormState=function(){baseUpdateFeishuFormState();const blockedPanel=[...document.querySelectorAll('.panel')].find(panel=>panel.querySelector('.warning')?.textContent.includes('权限不足')&&panel.querySelector('button[onclick^="startFeishuMigration"]'));if(!blockedPanel)return;blockedPanel.id='feishu-task-blocked-wiki';feishuPageBlocker={type:'wiki_permission',taskId:'blocked-wiki'};const nextText=document.querySelector('.migration-guide .panel-head > .pill');if(nextText)nextText.textContent='下一步：当前阻塞为目标 Wiki 读权；授权后重试原任务';const actionNote=blockedPanel.querySelector('.task-actions + .muted');if(actionNote)actionNote.textContent='当前阻塞：目标 Wiki 对应用不可见。请在飞书侧将该知识库或节点授予应用只读访问；完成后回到本任务点击“运行一次性迁入”，无需重填 Secret。';const nextButton=document.querySelector('#feishu-next-action');if(nextButton)nextButton.textContent=feishuNextButtonLabel(feishuReadiness?.nextAction)};
const localSectionLabels={replays:'线上分享回放',research_reports:'研究报告',group_digests:'群聊精华',books:'书籍',files_templates:'常用文件模板',benefits:'福利更新与领取',unclassified:'待分类（不可发布）'};
let selectedLocalFiles=[],localUploadReady=false,lastLocalUploadSummary=null;
function localSectionOptions(selected){if(selected==='reports_digest'||selected==='reports_digests')selected='research_reports';return Object.entries(localSectionLabels).filter(([value])=>value!=='unclassified'||selected==='unclassified').map(([value,label])=>`<option value="${value}" ${value===selected?'selected':''}>${label}</option>`).join('')}
function safeLocalDisplayName(name){return String(name||'资料').replace(/\\/g,'/').split('/').pop().normalize('NFC').replace(/[\u0000-\u001f\u007f]/g,'_').replace(/^[.=+@]+/,'_').slice(0,100)||'资料'}
function setLocalFiles(files){selectedLocalFiles=[...files].slice(0,20);const list=document.querySelector('#local-file-list');if(!list)return;const bulkSection=document.querySelector('#local-bulk-section')?.value||'research_reports',bulkTags=document.querySelector('#local-bulk-tags')?.value||'',bulkDownload=Boolean(document.querySelector('#local-download')?.checked);list.innerHTML=selectedLocalFiles.length?`<div class="hint"><b>已选 ${selectedLocalFiles.length} 个文件</b>；下面每项可单独覆盖，列表只显示安全文件名、类型、设置和待校验状态，不读取内容。</div>`+selectedLocalFiles.map((file,index)=>{const safeName=safeLocalDisplayName(file.name),extension=(safeName.split('.').pop()||'文件').toUpperCase(),title=safeName.replace(/\.[^.]+$/,'');return `<div class="local-file-row" data-index="${index}"><span class="file-kind">${esc(extension)}</span><div class="local-file-main"><b>${esc(safeName)}</b><label>标题<input class="form-input local-title" value="${esc(title)}" maxlength="120"></label><div class="form-grid local-file-settings"><label>资料分类<select class="form-input local-row-section">${localSectionOptions(bulkSection)}</select></label><label>关键词标签<input class="form-input local-row-tags" value="${esc(bulkTags)}" maxlength="249" placeholder="逗号或换行分隔"></label></div><label><input type="checkbox" class="local-row-download" ${bulkDownload?'checked':''}> 允许会员下载</label></div><span class="muted">待安全校验 · 不提供内容预览</span></div>`}).join(''):'<div class="hint">尚未选择文件。也可以在下方先创建“无文件资料条目”，之后补附件。</div>';document.querySelector('#local-upload-button').disabled=!selectedLocalFiles.length||!localUploadReady}
function applyBulkToSelectedLocalFiles(){const section=document.querySelector('#local-bulk-section').value,tags=document.querySelector('#local-bulk-tags').value,download=document.querySelector('#local-download').checked;document.querySelectorAll('#local-file-list .local-file-row').forEach(row=>{row.querySelector('.local-row-section').value=section;row.querySelector('.local-row-tags').value=tags;row.querySelector('.local-row-download').checked=download});const state=document.querySelector('#local-bulk-apply-state');if(state)state.textContent=`已批量应用到本批 ${selectedLocalFiles.length} 个待上传文件；仍可逐项覆盖。`}
function acceptLocalDrop(event){event.preventDefault();event.currentTarget.classList.remove('dragging');if(event.dataTransfer?.files?.length)setLocalFiles(event.dataTransfer.files)}
async function uploadLocalMaterials(){try{if(!selectedLocalFiles.length)throw new Error('请先选择文件');if(!confirm('确认这些资料的分类与公开元数据正确，已核对来源版权，并愿意承担本次文件安全与发布责任？安全校验通过的文件将立即发布到会员动态。'))throw new Error('已取消操作');const sourceNote=document.querySelector('#local-source-note').value,rows=[...document.querySelectorAll('#local-file-list .local-file-row')],metadata=selectedLocalFiles.map((file,index)=>{const row=rows.find(x=>Number(x.dataset.index)===index);return {title:row.querySelector('.local-title').value,summary:'',tags:row.querySelector('.local-row-tags').value,section:row.querySelector('.local-row-section').value,sourceNote,downloadEnabled:row.querySelector('.local-row-download').checked,needsClassification:false,operatorConfirmed:true,copyrightConfirmed:true,securityResponsibilityConfirmed:true}}),form=new FormData();form.append('metadata',JSON.stringify(metadata));selectedLocalFiles.forEach(file=>form.append('files',file));lastLocalUploadSummary=await requestJson('/api/admin/local-imports/upload',{method:'POST',body:form});selectedLocalFiles=[];await renderLocalMaterials()}catch(error){if(error.message!=='已取消操作')alert(error.message)}}
function renderLocalUploadResult(){if(!lastLocalUploadSummary)return '';const result=lastLocalUploadSummary,batch=result.batch||{},items=result.items||[],errors=result.errors||[];return `<div class="panel"><div class="panel-head"><div><h2>本批上传结果</h2><p class="muted">选择 ${batch.totalRows||0} 项 · 成功发布 ${batch.publishedRows||0} 项 · 待处理 ${batch.reviewRows||0} 项 · 异常 ${batch.errorRows||0} 项</p></div><span class="pill">${errors.length?'部分发布 / 部分异常':'已发布到会员动态'}</span></div><div class="queue-grid">${items.map((item,index)=>`<div class="ok"><b class="clamp-title" title="${esc(item.title)}">可用项 ${index+1} · ${esc(item.title)}</b><span>${esc(String(item.format||'').toUpperCase())} · ${esc(localSectionLabels[item.section]||item.section)} · 标签 ${(item.tags||[]).length} 个 · ${esc(display(item.status))}</span></div>`).join('')}${errors.map(error=>`<div class="warning"><b>文件 ${error.fileIndex}</b><span>${esc(error.code)}：${esc(error.message)}；其他合格文件已独立发布。</span></div>`).join('')}</div><div class="hint">这里只显示安全元数据，不显示本地路径、存储键、来源链接、附件引用或文件内容。</div></div>`}
function renderLocalBatchTools(batches,items){const editableStatuses=new Set(['pending_review','needs_classification']),cards=(batches||[]).map(batch=>{const eligible=items.filter(item=>item.batchId===batch.id&&editableStatuses.has(item.status));if(eligible.length<2)return '';const first=eligible[0];return `<div class="panel local-batch-tool" id="local-batch-tool-${esc(batch.id)}"><div class="panel-head"><div><h2>批量应用到本批（待审核）</h2><p class="muted">${eligible.length} 项可修改；已发布或已跳过资料不会被改变。</p></div><span class="pill">${esc(batch.id)}</span></div><div class="form-grid"><label>资料分类<select class="form-input batch-section">${localSectionOptions(first.section)}</select></label><label>关键词标签<input class="form-input batch-tags" value="${esc((first.tags||[]).join('，'))}" maxlength="249" placeholder="逗号或换行分隔，最多 10 个"></label></div><div class="bulk-bar"><label><input type="checkbox" class="batch-download" ${first.downloadEnabled?'checked':''}> 允许会员下载</label><button class="secondary" onclick="applyMetadataToLocalBatch('${batch.id}')">批量应用到本批</button><span class="muted">只修改待审核项；每项之后仍可单独覆盖。</span></div></div>`}).filter(Boolean);return cards.join('')}
async function applyMetadataToLocalBatch(batchId){try{const root=document.querySelector(`#local-batch-tool-${CSS.escape(batchId)}`),payload={section:root.querySelector('.batch-section').value,tags:root.querySelector('.batch-tags').value,downloadEnabled:root.querySelector('.batch-download').checked};await requestJson(`/api/admin/local-import-batches/${encodeURIComponent(batchId)}/apply-metadata`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});await renderLocalMaterials()}catch(error){alert(error.message)}}
async function createMetadataOnly(){try{const title=document.querySelector('#local-meta-title').value,tags=document.querySelector('#local-meta-tags').value,section=document.querySelector('#local-meta-section').value,sourceNote=document.querySelector('#local-meta-source').value;await requestJson('/api/admin/local-imports/metadata',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({items:[{title,summary:'',tags,section,sourceNote,downloadEnabled:false,needsClassification:false}]})});await renderLocalMaterials()}catch(error){alert(error.message)}}
async function updateLocalItem(id){try{const root=document.querySelector(`#local-item-${CSS.escape(id)}`),payload={title:root.querySelector('.edit-title').value,tags:root.querySelector('.edit-tags').value,section:root.querySelector('.edit-section').value,sourceNote:root.querySelector('.edit-source').value,downloadEnabled:root.querySelector('.edit-download').checked,needsClassification:root.querySelector('.edit-classification').checked};await requestJson(`/api/admin/local-import-items/${id}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});await renderLocalMaterials()}catch(error){alert(error.message)}}
async function reviewLocalItem(id,decision){try{const options={method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({decision,copyrightConfirmed:decision==='publish',securityConfirmed:decision==='publish'})};if(decision==='publish')await confirmedJson(`/api/admin/local-import-items/${id}/review`,options,'resource.publish','确认发布这条历史已上传资料？必须已核对分类、来源版权和文件安全责任；发布后将进入会员动态。');else if(decision==='unpublish')await confirmedJson(`/api/admin/local-import-items/${id}/review`,options,'resource.publish','确认取消发布？会员端资料库、搜索、动态、收藏和打开/下载入口将立即不可用，私有附件不会删除。');else await requestJson(`/api/admin/local-import-items/${id}/review`,options);await renderLocalMaterials()}catch(error){if(error.message!=='已取消操作')alert(error.message)}}
function removeTagCandidate(button){button.remove()}
function adoptTagSuggestions(id){const root=document.querySelector(`#local-item-${CSS.escape(id)}`),candidates=[...root.querySelectorAll('[data-tag-candidate]')].map(x=>x.dataset.tagCandidate);root.querySelector('.edit-tags').value=candidates.join('，')}
async function regenerateTagSuggestions(id){try{await requestJson(`/api/admin/local-import-items/${id}/tag-suggestions`,{method:'POST',headers:{'content-type':'application/json'},body:'{}'});await renderLocalMaterials()}catch(error){alert(error.message)}}
function renderTagSuggestion(item){const suggestion=item.tagSuggestion||{},candidates=suggestion.candidates||[],confirmed=item.tagStatus==='manual_confirmed';return `<div class="hint"><div class="panel-head"><div><b>自动建议标签（可修改）</b> · <span class="pill">${confirmed?'人工确认':'规则建议，待确认'}</span><p class="muted">${esc(suggestion.contentNotice||'当前仅使用标题、分类和文件名，未读取文件内容。')}</p></div><button class="secondary" onclick="regenerateTagSuggestions('${item.id}')">重新生成</button></div><div class="tag-candidates">${candidates.map(tag=>`<button type="button" class="secondary tag-candidate" data-tag-candidate="${esc(tag)}" onclick="removeTagCandidate(this)" title="点击删除这个候选">${esc(tag)} ×</button>`).join('')}</div><button class="secondary" onclick="adoptTagSuggestions('${item.id}')" ${candidates.length?'':'disabled'}>一键采用剩余建议</button><span class="muted">采用后仍可在“关键词标签”中编辑，点击保存才入库。本页不接收 AI API Key。</span></div>`}
function renderLocalItem(item){const workflowEditable=item.status!=='skipped',published=item.status==='published',historicalPublishable=['pending_review','unpublished'].includes(item.status)&&item.attachmentStatus==='stored'&&!item.needsClassification;return `<div class="panel" id="local-item-${esc(item.id)}"><div class="panel-head"><h2 class="clamp-title" title="${esc(item.title)}">${esc(item.title)} · <span class="pill">${esc(display(item.status))}</span></h2><span class="muted">${esc(item.format)} · ${item.attachmentStatus==='stored'?'附件已私有保存':'待补附件'}</span></div>${renderTagSuggestion(item)}<div class="form-grid"><label>标题<input class="form-input edit-title" value="${esc(item.title)}" maxlength="120" ${workflowEditable?'':'disabled'}></label><label>资料分类<select class="form-input edit-section" ${workflowEditable?'':'disabled'}>${localSectionOptions(item.section)}</select></label><label>关键词标签<input class="form-input edit-tags" value="${esc((item.tags||[]).join('，'))}" maxlength="249" placeholder="中文逗号或换行分隔，最多 10 个" ${workflowEditable?'':'disabled'}></label><label>来源说明<input class="form-input edit-source" value="${esc(item.sourceNote)}" maxlength="120" ${workflowEditable?'':'disabled'}></label></div><div class="bulk-bar"><label><input type="checkbox" class="edit-download" ${item.downloadEnabled?'checked':''} ${item.attachmentStatus==='stored'&&workflowEditable?'':'disabled'}> 允许会员下载</label><label><input type="checkbox" class="edit-classification" ${item.needsClassification?'checked':''} ${workflowEditable&&!published?'':'disabled'}> 需要人工确认分类</label><span class="muted">${published?'已发布资料会出现在会员动态；修改公开设置不会改变原发布时间。':'历史待处理资料只有在明确确认后才会发布。'} 在线预览能力待配置。</span></div>${workflowEditable?`<button class="secondary" onclick="updateLocalItem('${item.id}')">${published?'保存公开设置':'保存修改'}</button>`:''}${historicalPublishable?`<button class="primary" onclick="reviewLocalItem('${item.id}','publish')">发布已上传资料</button>`:''}${published?`<button class="secondary danger" onclick="reviewLocalItem('${item.id}','unpublish')">取消发布</button>`:''}${!published&&item.status!=='unpublished'&&item.status!=='skipped'?`<button class="secondary danger" onclick="reviewLocalItem('${item.id}','skip')">跳过</button>`:''}</div>`}
async function renderLocalMaterials(){const data=await requestJson('/api/admin/local-imports'),caps=data.capabilities;localUploadReady=Boolean(caps.privateStorageConfigured);const storageBadge=localUploadReady?'本机演示可用':'等待私有存储配置',storageNotice=localUploadReady?'当前不做内容转码、Office 公式执行或自动病毒扫描；ZIP 只作为附件包保存，不会解压执行。正式上线前必须接私有对象存储、病毒扫描和持久化数据库。':'上传接口已就绪，但当前服务未配置私有存储，因此上传按钮保持停用；配置 PRIVATE_STORAGE_DIR 并重启预览后可用。';content.innerHTML=`<div class="panel local-import-hero"><div class="panel-head"><div><h2>从电脑批量导入资料</h2><p class="muted">报告和书籍可多选 / 拖放 · 成功项统一进入待审核</p></div><span class="pill">${storageBadge}</span></div><div class="warning">${storageNotice}</div><div class="local-drop" ondragover="event.preventDefault();this.classList.add('dragging')" ondragleave="this.classList.remove('dragging')" ondrop="acceptLocalDrop(event)" onclick="document.querySelector('#local-files').click()"><b>选择多个报告或书籍，或一起拖拽文件到这里</b><span>优先支持 PDF、DOCX、Markdown、TXT；并保留 ${esc(caps.supportedFormats.join('、'))}。单文件最多 25MB，单批最多 20 个/100MB</span><input id="local-files" type="file" multiple hidden accept=".pdf,.docx,.xlsx,.pptx,.mp4,.mp3,.m4a,.png,.jpg,.jpeg,.md,.txt,.zip" onchange="setLocalFiles(this.files)"></div><div id="local-file-list"></div><div class="panel"><h2>批量应用到本批</h2><p class="muted">先设置统一分类、标签和下载开关，再一次应用到所有已选文件；每项仍可单独覆盖。</p><div class="form-grid"><label>批量资料分类<select id="local-bulk-section" class="form-input">${localSectionOptions('reports_digest')}</select></label><label>批量关键词标签<input id="local-bulk-tags" class="form-input" maxlength="249" placeholder="中文逗号或换行分隔，自动去重，最多 10 个"></label><label>来源说明<input id="local-source-note" class="form-input" value="本地迁入" maxlength="120"></label></div><div class="bulk-bar"><label><input id="local-download" type="checkbox"> 允许会员下载（只控制下载入口）</label><button class="secondary" type="button" onclick="applyBulkToSelectedLocalFiles()">批量应用到本批</button><span id="local-bulk-apply-state" class="muted">批量设置只作用于本批待上传文件。</span></div></div><div class="hint">上传后进入待审核，不会自动发布；发布仍需版权与文件安全确认。在线预览能力待配置，下载开关只控制下载入口。</div><button id="local-upload-button" class="primary" disabled onclick="uploadLocalMaterials()">批量上传到待审核区</button></div>${renderLocalUploadResult()}${renderLocalBatchTools(data.batches,data.items)}<div class="panel"><h2>先建条目，稍后补文件</h2><p class="muted">无文件条目可审核发布为说明类资料，但下载固定关闭，并进入待补附件队列。</p><div class="form-grid"><label>标题<input id="local-meta-title" class="form-input" maxlength="120" placeholder="资料标题"></label><label>分类<select id="local-meta-section" class="form-input">${localSectionOptions('reports_digest')}</select></label><label>关键词标签<input id="local-meta-tags" class="form-input" maxlength="249" placeholder="中文逗号或换行分隔"></label><label>来源说明<input id="local-meta-source" class="form-input" value="本地迁入" maxlength="120"></label></div><button class="secondary" onclick="createMetadataOnly()">创建无文件条目</button></div><div class="panel-head local-review-head"><h2>本地导入审核队列</h2><span class="muted">${data.items.length} 项 · 仅展示当前运行中的安全导入记录</span></div>${data.items.length?data.items.map(renderLocalItem).join(''):'<div class="hint">暂无本地导入项。</div>'}`;setLocalFiles(selectedLocalFiles)}
const baseRenderLocalMaterials=renderLocalMaterials;
renderLocalMaterials=async function(){await baseRenderLocalMaterials();const heroPanel=document.querySelector('.local-import-hero'),heroWarning=heroPanel?.querySelector('.warning');if(heroPanel?.querySelector('.panel-head .muted'))heroPanel.querySelector('.panel-head .muted').textContent='报告和书籍可多选 / 拖放 · 安全校验成功即发布';if(heroWarning)heroWarning.insertAdjacentHTML('afterend','<div class="hint"><b>受控运营上传即发布：</b>点击上传时一次确认分类、来源版权和文件安全责任；成功项立即进入会员动态，失败项单独报告。含会员身份、联系方式或同意状态的名册文件不要作为普通资料上传，请到“会员 → 公开名册 / 公开名册审核”处理。</div>');const uploadButton=document.querySelector('#local-upload-button');if(uploadButton)uploadButton.textContent='确认责任并上传发布';const publishHint=[...(heroPanel?.querySelectorAll('.hint')||[])].find(x=>x.textContent.includes('上传后进入待审核'));if(publishHint)publishHint.textContent='上传前请完成分类、标签、下载设置并确认责任；安全校验成功后直接发布到会员动态。在线预览能力待配置，下载开关只控制下载入口。';const reviewHead=document.querySelector('.local-review-head h2'),reviewCount=document.querySelector('.local-review-head .muted');if(reviewHead)reviewHead.textContent='已发布资料管理与历史待处理';if(reviewCount)reviewCount.textContent=reviewCount.textContent.replace('本地导入审核队列','本地导入记录')};
const baseRenderDashboard=renderDashboard;
renderDashboard=async function(){await baseRenderDashboard();const hero=document.querySelector('.local-import-hero .muted');if(hero)hero.textContent='资料迁入首选路径 · 受控运营上传校验成功即发布';for(const label of document.querySelectorAll('.card span'))if(label.textContent==='资料待审核')label.textContent='公开名册待审核'};
async function renderPublishedResources(){const rows=await requestJson('/api/admin/resources'),published=rows.filter(x=>x.status==='published');content.innerHTML=`<div class="panel"><div class="panel-head"><div><h2>已发布资料管理</h2><p class="muted">上传成功的资料按发布时间进入会员动态；可取消发布。本页不展示私有附件路径、存储键或来源链接。</p></div><span class="pill">${published.length} 项已发布</span></div></div>${published.length?published.map(item=>`<div class="panel"><div class="panel-head"><div><h2 class="clamp-title" title="${esc(item.title)}">${esc(item.title)}</h2><p class="muted">${esc(localSectionLabels[resolveAdminResourceSection(item)]||display(item.type))} · ${item.publishedAt?new Date(item.publishedAt).toLocaleString('zh-CN'):'已发布'}</p></div><span class="pill">已发布</span></div>${item.tags?.length?`<p>${item.tags.map(tag=>`<span class="pill">${esc(tag)}</span>`).join(' ')}</p>`:''}<div class="bulk-bar">${item.localImportItemId?`<button class="secondary" onclick="openLocalItemFromManagement('${esc(item.localImportItemId)}')">编辑公开设置</button>`:''}<button class="secondary danger" onclick="unpublishManagedResource('${esc(item.id)}','${esc(item.localImportItemId||'')}')">取消发布</button></div></div>`).join(''):'<div class="hint">暂无已发布资料。</div>'}`}
function resolveAdminResourceSection(item){return item.mobileSection||({industry_report:'research_reports',group_digest:'group_digests',meeting_replay:'replays',book:'books',benefit_update:'benefits'}[item.type]||'files_templates')}
async function openLocalItemFromManagement(itemId){await load('local-materials');document.querySelector(`#local-item-${CSS.escape(itemId)}`)?.scrollIntoView({behavior:'smooth',block:'start'})}
async function unpublishManagedResource(resourceId,localItemId){try{if(localItemId){await confirmedJson(`/api/admin/local-import-items/${localItemId}/review`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({decision:'unpublish'})},'resource.publish','确认取消发布？会员端资料库、搜索、动态、收藏和打开/下载入口将立即不可用，私有附件不会删除。')}else{if(!confirm('确认取消发布？会员端将立即不可见，原记录和审计保留。'))return;await requestJson(`/api/admin/resources/${resourceId}/review`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({status:'archived'})})}await renderPublishedResources()}catch(error){if(error.message!=='已取消操作')alert(error.message)}}
const baseLoadView=loadView;
loadView=async function(key){if(key==='members'){const rows=await requestJson('/api/admin/members');content.innerHTML=renderMembers(rows);mountMemberPaymentImport();return}if(key==='local-materials')return renderLocalMaterials();if(key==='resources')return renderPublishedResources();if(key==='matching-rehearsal')return renderMatchingRehearsal();return baseLoadView(key)};
loadSession().then(()=>navigate('workbench','dashboard')).catch(e=>{content.innerHTML=`<div class="error">${esc(e.message)}</div>`});
